        ["PowerEditor.AggressiveModeWarningMessage"] = "Aggressive mode will keep CPU at 100% minimum frequency for ultimate performance.\n\n⚠️ Please note the following risks:\n\n• Temperature Increase: CPU temperature may rise 10-15°C\n• Power Consumption: System power may increase 20-30%\n• Noise Level: Fan speed will increase noticeably\n• Stability: Some systems may become unstable\n\n💡 Recommendations:\n• Ensure good cooling system (tower cooler or liquid cooling)\n• Monitor temperature, avoid exceeding 85°C\n• Use only during gaming, disable for daily use\n\nAre you sure you want to enable aggressive mode?",
