        // OPT-003: Aggressive Mode Detailed Information
        ["AggressiveMode.DetailTitle"] = "🔥 Aggressive Mode Details",
        ["AggressiveMode.DetailMessage"] = @"【What is Aggressive Mode?】
Aggressive mode further boosts performance beyond smart optimization by adjusting power management parameters to reduce CPU throttling and core parking, ideal for users seeking maximum frame rates.

【Parameter Adjustments】
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Parameter               Standard → Aggressive
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Min Processor State     85-95%   → 100%
Perf Check Interval     1000ms   → 500ms
Core Parking Min        70-90%   → 100%
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

【Special Handling】
• AMD Ryzen X3D Series: Min Processor State stays at 90%
  (Prevents 3D V-Cache performance degradation)
• Other CPUs: All parameters maximized

【Potential Impact】
✅ Performance Gains
  • Faster CPU response, reduced throttling delay
  • Possible slight FPS improvement
  • Ideal for competitive gaming

⚠️ Side Effects
  • Power Consumption: CPU runs at high frequency continuously
  • Temperature Rise: Increased cooling demand
  • Fan Noise: May become more noticeable
  • Battery Life: Reduced laptop battery duration

【Usage Recommendations】
• Desktop: Safe to use (with good cooling)
• Laptop: Recommended when plugged in, monitor cooling
• Disable if temperature is too high or noise is excessive
• Not recommended for extended use (disable during office work)

【Transparency Statement】
This software only adjusts Windows power plan parameters. It does not modify BIOS settings or perform hardware overclocking. All adjustments are reversible by disabling aggressive mode.",
        
