        ["About.ToPlayersTitle"] = "To Gamers",
        ["About.ToPlayersContent"] = "Hi, I'm Zhiyu, also known as Yuqi (same person).\n\nThis project exists to turn proven, reversible optimization practices into something ordinary users can understand and use safely.\n\nPlease read each optimization's change details and consequences before enabling it.",
        ["About.WhyNameTitle"] = "Why \"Yuqi\"?",
        ["About.WhyNameContent"] = "\"Yu\" comes from my name and symbolizes infinite possibilities like the universe; \"Qi\" means wonder and miracle — I hope this software brings miraculous improvements to your gaming experience.",
        ["About.FirstVersionNote"] = "This is the first version of Yuqi Engine, and there's still a lot to improve. But I'll keep iterating to make it the best game optimization tool out there.",
        ["About.Wish"] = "May every frame be smooth, every match be enjoyable.",
        ["About.SupportTitle"] = "Voluntary Support",
        ["About.SupportContent"] = "Yuqi Engine is free software, not a paywall.\nIf it helps you, you can voluntarily support the author.",
        ["About.FreeNotice"] = "Anti-resale notice: this software is always free. If you paid for it, please report the seller.",
