        ["About.EffectContent"] = "This software optimizes game performance by adjusting system settings. Results vary depending on hardware and system environment — 100% FPS improvement is not guaranteed.\n\nLow-end PCs may see more noticeable improvements, while high-end PCs may see limited gains. Test your games after optimization to decide whether to keep the settings.",
        ["About.WarningTitle"] = "Important Notice",
